// Calculate this week's date range
const now = new Date();
const day = now.getDay();
const diff = now.getDate() - day + (day === 0 ? -6 : 1); // Monday
const monday = new Date(now.setDate(diff));
const friday = new Date(monday);
friday.setDate(friday.getDate() + 4);
friday.setHours(23, 59, 59, 999);

// Config from environment or static values
const repoOwner = $env.GITHUB_REPO_OWNER || 'owner';
const repoName = $env.GITHUB_REPO_NAME || 'repo';
const githubToken = $env.GITHUB_TOKEN || '';
const language = $env.SUMMARY_LANGUAGE || 'EN';
const webhookUrl = $env.WEBHOOK_URL || '';

return {
  json: {
    repo_owner: repoOwner,
    repo_name: repoName,
    github_api: 'https://api.github.com',
    week_start: monday.toISOString(),
    week_end: friday.toISOString(),
    language: language,
    webhook_url: webhookUrl,
    github_token: githubToken
  }
};

// Combine all GitHub data into a structured prompt for Claude
const commits = items.find(i => i.node.name === 'Fetch Commits')?.json || [];
const issues = items.find(i => i.node.name === 'Fetch Closed Issues')?.json || [];
const prs = items.find(i => i.node.name === 'Fetch Merged PRs')?.json || [];

const config = $json; // From Set Variables node

// Parse arrays if they're strings
let commitList = commits;
let issueList = issues;
let prList = prs;
if (typeof commits === 'string') try { commitList = JSON.parse(commits); } catch(e) { commitList = []; }
if (typeof issues === 'string') try { issueList = JSON.parse(issues); } catch(e) { issueList = []; }
if (typeof prs === 'string') try { prList = JSON.parse(prs); } catch(e) { prList = []; }

// Handle GitHub API wrapping
if (Array.isArray(commitList)) {
  // Already an array, use as-is
} else if (commitList && typeof commitList === 'object') {
  commitList = Array.isArray(commitList.data) ? commitList.data : [commitList];
} else {
  commitList = [];
}
if (Array.isArray(issueList)) {
  // Already an array
} else if (issueList && typeof issueList === 'object') {
  issueList = Array.isArray(issueList.data) ? issueList.data : [issueList];
} else {
  issueList = [];
}
if (Array.isArray(prList)) {
  // Already an array
} else if (prList && typeof prList === 'object') {
  prList = Array.isArray(prList.data) ? prList.data : [prList];
} else {
  prList = [];
}

// Build summary text
const commitMessages = commitList.map(c => 
  `- ${c.commit?.message?.split('\n')[0] || c.message || 'no message'} (${c.sha?.substring(0,7)}) by ${c.commit?.author?.name || 'unknown'}"
).join('\n');

const issueTitles = issueList.map(i => 
  `- #${i.number}: ${i.title} (closed by ${i.closed_by?.login || 'unknown'})"
).join('\n');

const prTitles = prList.filter(p => p.merged_at).map(p => 
  `- #${p.number}: ${p.title} (merged by ${p.merged_by?.login || 'unknown'})"
).join('\n');

const lang = config.language || 'EN';
const greeting = lang === 'FR' ? 'Voici le résumé' : 'Here is the summary';
const weekLabel = lang === 'FR' ? 'Semaine du' : 'Week of';

const userPrompt = `${greeting} ${weekLabel} ${new Date(config.week_start).toLocaleDateString(lang === 'FR' ? 'fr-FR' : 'en-US')} to ${new Date(config.week_end).toLocaleDateString(lang === 'FR' ? 'fr-FR' : 'en-US')} for **${config.repo_owner}/${config.repo_name}**.

## 📊 Commits This Week (${commitList.length})
${commitList.length > 0 ? commitMessages : '- No commits found'}

## ✅ Issues Closed (${issueList.length})
${issueList.length > 0 ? issueTitles : '- No issues closed'}

## 🔀 PRs Merged (${prList.length})
${prList.length > 0 ? prTitles : '- No PRs merged'}

---
Please generate a concise, narrative weekly development summary in ${lang === 'FR' ? 'French' : 'English':
- Highlight key accomplishments and patterns
- Mention any notable collaborations
- Keep it under 300 words
- Use a professional but engaging tone
- Format with markdown headers and bullet points`;

return {
  json: {
    prompt: userPrompt,
    config: config
  }
};
